package com.example.data.model

/*
 * All 494 upazilas of Bangladesh, grouped by division. Generated from
 * https://github.com/nuhil/bangladesh-geocode (MIT, see licenses/bangladesh-geocode-MIT.txt).
 * Upazilas have no coordinates there, so each uses its district centre (fine for area matching;
 * GPS auto-detect only uses BANGLADESH_DISTRICTS, which have real coordinates).
 */

private fun upazila(key: String, en: String, bn: String, lat: Double, lng: Double, nameEn: String, nameBn: String, divEn: String, divBn: String) =
    BangladeshDistrict(
        areaKey = key, nameEn = en, nameBn = bn, latitude = lat, longitude = lng,
        defaultHospitalEn = "$nameEn Upazila Health Complex", defaultHospitalBn = "$nameBn উপজেলা স্বাস্থ্য কমপ্লেক্স",
        divisionEn = divEn, divisionBn = divBn
    )

